// Parse request and validate
const query = $input.item.json.query || {};
const action = query.action || 'get_questions';
const studentId = parseInt(query.studentId) || 999;
const topicId = parseInt(query.topicId);
const questionId = parseInt(query.questionId);
const difficulty = query.difficulty || 'medium';
const count = Math.min(parseInt(query.count) || 5, 20);
const questionType = query.questionType || null;

// For submit action
const studentAnswer = query.answer || '';
const timeSpent = parseInt(query.timeSpent) || 0;
const hintUsed = query.hintUsed === 'true' || query.hintUsed === true;

// Validate required fields
if (action === 'get_questions' && !topicId) {
  return {
    json: {
      error: true,
      message: 'topicId is required for get_questions action'
    }
  };
}

if (action === 'submit_answer' && (!questionId || !studentAnswer)) {
  return {
    json: {
      error: true,
      message: 'questionId and answer are required for submit_answer action'
    }
  };
}

// Sanitize inputs
const sanitize = (str, maxLength = 5000) => {
  if (typeof str !== 'string') return '';
  return str.slice(0, maxLength).trim();
};

return {
  json: {
    action,
    studentId,
    topicId: topicId || null,
    questionId: questionId || null,
    difficulty: ['foundation', 'medium', 'higher', 'challenge'].includes(difficulty) ? difficulty : 'medium',
    count,
    questionType,
    studentAnswer: sanitize(studentAnswer, 5000),
    timeSpent,
    hintUsed,
    timestamp: new Date().toISOString()
  }
};

// Prepare AI grading prompt
const question = $input.first().json;
const request = $('Parse Request').item.json;

if (!question || !question.question_id) {
  return {
    json: {
      error: true,
      message: 'Question not found'
    }
  };
}

// Parse mark scheme if string
let markScheme = question.mark_scheme;
if (typeof markScheme === 'string') {
  try {
    markScheme = JSON.parse(markScheme);
  } catch (e) {
    markScheme = { total_marks: question.marks_available };
  }
}

// Build grading prompt
const gradingPrompt = `You are an expert GCSE examiner. Grade the following student answer according to the mark scheme.

**Question:** ${question.question_text}

**Command Word:** ${question.command_word || 'Answer'}

**Marks Available:** ${question.marks_available}

**Mark Scheme:**
${JSON.stringify(markScheme, null, 2)}

**Model Answer:** ${question.correct_answer}

**Acceptable Answers:** ${(question.acceptable_answers || []).join(', ') || 'See mark scheme'}

**Student Answer:** ${request.studentAnswer}

---

**Your Task:**
1. Award marks based on the mark scheme criteria
2. Identify which marking points were achieved
3. Provide specific, constructive feedback
4. Suggest improvements aligned with the mark scheme
5. Note any common errors from: ${(question.common_errors || []).join(', ')}

**Respond in JSON format:**
{
  "marks_awarded": <number>,
  "is_correct": <boolean>,
  "marking_points": [
    {"point": "...", "awarded": 1/0, "comment": "..."}
  ],
  "overall_feedback": "...",
  "strengths": ["..."],
  "improvements": ["..."],
  "next_steps": "..."
}`;

return {
  json: {
    prompt: gradingPrompt,
    questionId: question.question_id,
    marksAvailable: question.marks_available,
    studentAnswer: request.studentAnswer,
    studentId: request.studentId,
    timeSpent: request.timeSpent,
    hintUsed: request.hintUsed
  }
};

// Parse AI grading response
const aiResponse = $input.first().json.message?.content || $input.first().json.text || '';
const questionData = $('Prepare Grading Prompt').item.json;

let feedback = {};
try {
  // Try to parse JSON response
  const jsonMatch = aiResponse.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    feedback = JSON.parse(jsonMatch[0]);
  } else {
    // Fallback parsing
    feedback = {
      marks_awarded: 0,
      is_correct: false,
      overall_feedback: aiResponse,
      marking_points: [],
      strengths: [],
      improvements: ['Could not parse detailed feedback']
    };
  }
} catch (e) {
  feedback = {
    marks_awarded: 0,
    is_correct: false,
    overall_feedback: aiResponse.slice(0, 500),
    marking_points: [],
    strengths: [],
    improvements: ['Error parsing feedback']
  };
}

return {
  json: {
    questionId: questionData.questionId,
    studentId: questionData.studentId,
    studentAnswer: questionData.studentAnswer,
    marksAwarded: feedback.marks_awarded || 0,
    marksPossible: questionData.marksAvailable,
    isCorrect: feedback.is_correct || false,
    feedback: feedback,
    timeSpent: questionData.timeSpent,
    hintUsed: questionData.hintUsed
  }
};

// Build questions response
const questions = $input.all().map(item => item.json);

// Parse JSONB fields
const parseJson = (field) => {
  if (!field) return null;
  if (typeof field === 'string') {
    try {
      return JSON.parse(field);
    } catch (e) {
      return null;
    }
  }
  return field;
};

return {
  json: {
    success: true,
    questions: questions.map(q => ({
      id: q.question_id,
      type: q.question_type,
      difficulty: q.difficulty,
      text: q.question_text,
      data: parseJson(q.question_data),
      marksAvailable: q.marks_available,
      answerType: q.answer_type,
      workingRequired: q.working_required,
      commandWord: q.command_word,
      hint: q.hint_text,
      specificationRef: q.specification_ref,
      examBoard: q.exam_board,
      topic: q.topic_name
    })),
    meta: {
      totalQuestions: questions.length,
      difficulty: $('Parse Request').item.json.difficulty,
      topicId: $('Parse Request').item.json.topicId,
      timestamp: new Date().toISOString()
    }
  }
};

// Build submission response
const result = $input.first().json;
const savedData = $input.first().json;

return {
  json: {
    success: true,
    result: {
      attemptId: savedData.attempt_id,
      marksAwarded: result.marksAwarded,
      marksPossible: result.marksPossible,
      isCorrect: result.isCorrect,
      percentageScore: Math.round((result.marksAwarded / result.marksPossible) * 100),
      feedback: result.feedback
    },
    xpGained: result.isCorrect ? 15 : 5,
    encouragement: result.isCorrect 
      ? '🎉 Excellent work! Keep it up!' 
      : '💪 Good effort! Review the feedback and try similar questions.',
    meta: {
      timestamp: new Date().toISOString()
    }
  }
};

return {
  json: {
    success: false,
    error: 'Unknown action',
    validActions: ['get_questions', 'submit_answer']
  }
};

